def islands_after_adds(rows: int, cols: int, positions: list[tuple[int, int]]) -> list[int]:
    parent = {}
    rank = {}
    land = set()
    island_count = 0
    result = []

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    for r, c in positions:
        idx = r * cols + c
        if idx in land:
            result.append(island_count)
            continue

        land.add(idx)
        parent[idx] = idx
        rank[idx] = 0
        island_count += 1

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nidx = nr * cols + nc
                if nidx in land:
                    if union(idx, nidx):
                        island_count -= 1

        result.append(island_count)

    return result

