import re
from typing import List, Tuple, Union

Token = Union[str, float]

def tokenize(expr: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        if expr[i].isspace():
            i += 1
            continue

        # Check for **
        if expr[i:i+2] == '**':
            tokens.append('**')
            i += 2
            continue

        # Check for other operators
        if expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
            continue

        # Number (integer or decimal, including .5 format)
        if expr[i].isdigit() or (expr[i] == '.' and i + 1 < n and expr[i+1].isdigit()):
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1
            tokens.append(float(expr[i:j]))
            i = j
            continue

        raise ValueError(f"Invalid character: {expr[i]}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self.parse_additive()
        if self.pos < len(self.tokens):
            raise ValueError("Unexpected token after expression")
        return result

    def parse_additive(self) -> float:
        """Parse + and - (lowest precedence, left-associative)"""
        left = self.parse_multiplicative()

        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_multiplicative()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_multiplicative(self) -> float:
        """Parse * and / (left-associative)"""
        left = self.parse_power()

        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_power()
            if op == '*':
                left = left * right
            else:
                left = left / right

        return left

    def parse_power(self) -> float:
        """Parse ** (right-associative)"""
        base = self.parse_unary()

        if self.peek() == '**':
            self.consume()
            # For right-associativity, recursively call parse_power
            # But we need to handle the case where the right side starts with unary
            exponent = self.parse_power_right()
            return base ** exponent

        return base

    def parse_power_right(self) -> float:
        """Parse the right side of ** which can start with unary operators"""
        return self.parse_unary()

    def parse_unary(self) -> float:
        """Parse unary + and -"""
        if self.peek() == '+':
            self.consume()
            return +self.parse_unary()
        elif self.peek() == '-':
            self.consume()
            return -self.parse_unary()
        else:
            return self.parse_primary()

    def parse_primary(self) -> float:
        """Parse numbers and parenthesized expressions"""
        token = self.peek()

        if isinstance(token, float):
            self.consume()
            return token

        if token == '(':
            self.consume()
            result = self.parse_additive()
            if self.peek() != ')':
                raise ValueError("Expected closing parenthesis")
            self.consume()
            return result

        raise ValueError(f"Unexpected token: {token}")

def calc(expr: str) -> float:
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")
    parser = Parser(tokens)
    return parser.parse()
