        sign = -1
        words = words[1:]

    total = 0
    current_chunk = 0

    for word in words:
        if word == 'and':
            continue

        if word in ones:
            current_chunk += ones[word]
        elif word in tens:
            current_chunk += tens[word]
        elif word in scales:
            if word == 'hundred':
                current_chunk *= 100
            else:
                # thousand, million, billion
                total += current_chunk * scales[word]
                current_chunk = 0

    total += current_chunk
    return total * sign

