        needed = len(word) + (1 if current_line else 0)

        if current_len + needed > width:
            # Line is full, justify and reset
            result.append(format_line(current_line, False))
            current_line = [word]
            current_len = len(word)
        else:
            # Add word to current line
            current_line.append(word)
            current_len += needed

    # Handle the last line
    if current_line:
        result.append(format_line(current_line, True))

    return result

