def count_n_queens(n: int) -> int:
    def backtrack(cols: int, diag1: int, diag2: int) -> int:
        if cols == (1 << n) - 1:
            return 1

        count = 0
        available = ((1 << n) - 1) & ~(cols | diag1 | diag2)

        while available:
            pos = available & -available
            available -= pos

            count += backtrack(
                cols | pos,
                (diag1 | pos) << 1,
                (diag2 | pos) >> 1
            )

        return count

    return backtrack(0, 0, 0)

