def num_decodings(s: str) -> int:
    MOD = 1_000_000_007

    if not s:
        return 0

    n = len(s)

    # prev2 represents dp[i-2], prev1 represents dp[i-1]
    prev2 = 1  # Base case: empty string has 1 way
    prev1 = 0

    # Handle first character
    if s[0] == '0':
        return 0
    elif s[0] == '*':
        prev1 = 9
    else:
        prev1 = 1

    for i in range(1, n):
        curr = 0

        # Single character decoding
        if s[i] == '0':
            single = 0
        elif s[i] == '*':
            single = 9
        else:
            single = 1

        curr = (curr + single * prev1) % MOD

        # Two character decoding
        if s[i-1] == '0':
            pass  # Cannot start with 0
        elif s[i-1] == '*':
            if s[i] == '*':
                # ** can be 11-19 (9) + 21-26 (6) = 15
                double = 15
            elif s[i] >= '0' and s[i] <= '6':
                # *0-*6 can be 10-16 or 20-26 = 2 ways
                double = 2
            else:
                # *7-*9 can only be 17-19 = 1 way
                double = 1
        else:
            if s[i] == '*':
                if s[i-1] == '1':
                    # 1* can be 11-19 = 9 ways
                    double = 9
                elif s[i-1] == '2':
                    # 2* can be 21-26 = 6 ways
                    double = 6
                else:
                    double = 0
            else:
                val = int(s[i-1:i+1])
                if 10 <= val <= 26:
                    double = 1
                else:
                    double = 0

        curr = (curr + double * prev2) % MOD

        prev2, prev1 = prev1, curr

    return prev1

