def parse_json(text: str) -> object:
    class _JSONParser:
        def __init__(self, text):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def peek(self):
            if self.pos < self.length:
                return self.text[self.pos]
            return ''

        def consume(self):
            char = self.peek()
            self.pos += 1
            return char

        def skip_whitespace(self):
            while self.pos < self.length and self.text[self.pos] in ' \t\n\r':
                self.pos += 1

        def parse(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Empty input")
            value = self.parse_value()
            self.skip_whitespace()
            if self.pos < self.length:
                raise ValueError("Trailing characters")
            return value

        def parse_value(self):
            self.skip_whitespace()
            char = self.peek()
            if char == '{':
                return self.parse_object()
            elif char == '[':
                return self.parse_array()
            elif char == '"':
                return self.parse_string()
            elif char == 't':
                return self.parse_true()
            elif char == 'f':
                return self.parse_false()
            elif char == 'n':
                return self.parse_null()
            elif char == '-' or char.isdigit():
                return self.parse_number()
            elif char == "'":
                raise ValueError("Single quotes are not allowed")
            else:
                raise ValueError(f"Unexpected character: {char}")

        def parse_object(self):
            self.consume() # consume '{'
            result = {}
            self.skip_whitespace()

            if self.peek() == '}':
                self.consume()
                return result

            while True:
                self.skip_whitespace()
                if self.peek() != '"':
                    raise ValueError("Expected string key")

                key = self.parse_string()

                self.skip_whitespace()
                if self.peek() != ':':
                    raise ValueError("Expected ':'")
                self.consume()

                self.skip_whitespace()
                value = self.parse_value()
                result[key] = value

                self.skip_whitespace()
                char = self.peek()
                if char == '}':
                    self.consume()
                    return result
                elif char == ',':
                    self.consume()
                    self.skip_whitespace()
                    if self.peek() == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError(f"Expected ',' or '}}'")

        def parse_array(self):
            self.consume() # consume '['
            result = []
            self.skip_whitespace()

            if self.peek() == ']':
                self.consume()
                return result

            while True:
                self.skip_whitespace()
                value = self.parse_value()
                result.append(value)

                self.skip_whitespace()
                char = self.peek()
                if char == ']':
                    self.consume()
                    return result
                elif char == ',':
                    self.consume()
                    self.skip_whitespace()
                    if self.peek() == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError(f"Expected ',' or ']'")

        def parse_string(self):
            self.consume() # consume '"'
            result = []
            while True:
                char = self.peek()
                if not char:
                    raise ValueError("Unterminated string")
                if char == '"':
                    self.consume()
                    return ''.join(result)
                if char == '\\':
                    self.consume()
                    escape_char = self.peek()
                    if not escape_char:
                        raise ValueError("Unterminated string escape")

                    if escape_char == '"':
                        result.append('"')
                    elif escape_char == '\\':
                        result.append('\\')
                    elif escape_char == '/':
                        result.append('/')
                    elif escape_char == 'b':
                        result.append('\b')
                    elif escape_char == 'f':
                        result.append('\f')
                    elif escape_char == 'n':
                        result.append('\n')
                    elif escape_char == 'r':
                        result.append('\r')
                    elif escape_char == 't':
                        result.append('\t')
                    elif escape_char == 'u':
                        self.consume()
                        hex_chars = ""
                        for _ in range(4):
                            h = self.peek()
                            if not h or h not in '0123456789abcdefABCDEF':
                                raise ValueError("Invalid unicode escape")
                            hex_chars += h
                            self.consume()
                        code_point = int(hex_chars, 16)
                        result.append(chr(code_point))
                    else:
                        raise ValueError(f"Invalid escape sequence: \\{escape_char}")
                    self.consume()
                else:
                    result.append(char)
                    self.consume()

        def parse_number(self):
            start_pos = self.pos
            is_float = False

            # Sign
            if self.peek() == '-':
                self.consume()

            # Integer part
            if self.peek() == '0':
                self.consume()
                if self.peek().isdigit():
                    raise ValueError("Leading zeros not allowed")
            elif self.peek().isdigit():
                while self.peek().isdigit():
                    self.consume()
            else:
                raise ValueError("Invalid number format")

            # Fraction
            if self.peek() == '.':
                is_float = True
                self.consume()
                if not self.peek().isdigit():
                    raise ValueError("Fraction must contain digits")
                while self.peek().isdigit():
                    self.consume()

            # Exponent
            if self.peek() in ('e', 'E'):
                is_float = True
                self.consume()
                if self.peek() in ('+', '-'):
                    self.consume()
                if not self.peek().isdigit():
                    raise ValueError("Exponent must contain digits")
                while self.peek().isdigit():
                    self.consume()

            num_str = self.text[start_pos:self.pos]
            if is_float:
                return float(num_str)
            else:
                return int(num_str)

        def parse_true(self):
            if self.text[self.pos:self.pos+4] == 'true':
                self.pos += 4
                return True
            raise ValueError("Invalid literal true")

        def parse_false(self):
            if self.text[self.pos:self.pos+5] == 'false':
                self.pos += 5
                return False
            raise ValueError("Invalid literal false")

        def parse_null(self):
            if self.text[self.pos:self.pos+4] == 'null':
                self.pos += 4
                return None
            raise ValueError("Invalid literal null")

    return _JSONParser(text).parse()

