def islands_after_adds(rows: int, cols: int, positions: list[tuple[int, int]]) -> list[int]:
    parent = {}
    rank = {}

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    land = set()
    island_count = 0
    result = []

    for r, c in positions:
        pos = (r, c)

        if pos in land:
            result.append(island_count)
            continue

        land.add(pos)
        parent[pos] = pos
        rank[pos] = 0
        island_count += 1

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            neighbor = (nr, nc)

            if 0 <= nr < rows and 0 <= nc < cols and neighbor in land:
                if union(pos, neighbor):
                    island_count -= 1

        result.append(island_count)

    return result

