def kth_smallest_distance(nums: list[int], k: int) -> int:
    nums.sort()
    n = len(nums)

    def check(dist: int) -> bool:
        count = 0
        left = 0
        for right in range(n):
            while nums[right] - nums[left] > dist:
                left += 1
            count += (right - left)
            if count >= k:
                return True
        return False

    low = 0
    high = nums[-1] - nums[0]
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans

