def tokenize(expr: str):
    pattern = r'\s*([a-zA-Z_][a-zA-Z0-9_]*|\(|\)|true|false|not|and|or)'
    tokens = []
    pos = 0
    while pos < len(expr):
        match = re.match(pattern, expr[pos:])
        if not match:
            raise SyntaxError(f"Unexpected character at position {pos}: '{expr[pos]}'")
        token = match.group(1)
        tokens.append(token)
        pos += match.end()
    return tokens


class Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.pos = 0
        self.env = env

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        token = self.peek()
        self.pos += 1
        return token

    def parse_or_expr(self):
        left = self.parse_and_expr()
        while self.peek() == 'or':
            self.consume()
            right = self.parse_and_expr()
            left = left or right
        return left

    def parse_and_expr(self):
        left = self.parse_not_expr()
        while self.peek() == 'and':
            self.consume()
            right = self.parse_not_expr()
            left = left and right
        return left

    def parse_not_expr(self):
        if self.peek() == 'not':
            self.consume()
            operand = self.parse_not_expr()
            return not operand
        return self.parse_primary()

    def parse_primary(self):
        token = self.peek()
        if token is None:
            raise SyntaxError("Unexpected end of expression")

        if token == '(':
            self.consume()
            result = self.parse_or_expr()
            if self.peek() != ')':
                raise SyntaxError("Expected closing parenthesis")
            self.consume()
            return result
        elif token == 'true':
            self.consume()
            return True
        elif token == 'false':
            self.consume()
            return False
        else:
            self.consume()
            if token not in self.env:
                raise KeyError(token)
            return self.env[token]
