import re
from typing import List, Tuple, Union

Token = Tuple[str, Union[str, float]]

def tokenize(expr: str) -> List[Token]:
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        if expr[i].isspace():
            i += 1
            continue

        # Number (including .5 format)
        if expr[i].isdigit() or (expr[i] == '.' and i + 1 < n and expr[i + 1].isdigit()):
            j = i
            has_dot = False
            while j < n and (expr[j].isdigit() or (expr[j] == '.' and not has_dot)):
                if expr[j] == '.':
                    has_dot = True
                j += 1
            tokens.append(('NUM', float(expr[i:j])))
            i = j
            continue

        # Two-character operators
        if i + 1 < n and expr[i:i+2] in ('**'):
            tokens.append(('OP', expr[i:i+2]))
            i += 2
            continue

        # Single character operators and parentheses
        if expr[i] in '+-*/()':
            tokens.append(('OP', expr[i]))
            i += 1
            continue

        raise ValueError(f"Invalid character: {expr[i]}")

    return tokens

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token

    def parse(self) -> float:
        result = self.parse_additive()
        if self.pos < len(self.tokens):
            raise ValueError("Unexpected token after expression")
        return result

    def parse_additive(self) -> float:
        """Parse + and - (lowest precedence, left-associative)"""
        left = self.parse_multiplicative()

        while self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in ('+', '-'):
            op = self.consume()[1]
            right = self.parse_multiplicative()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_multiplicative(self) -> float:
        """Parse * and / (left-associative)"""
        left = self.parse_power()

        while self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in ('*', '/'):
            op = self.consume()[1]
            right = self.parse_power()
            if op == '*':
                left = left * right
            else:
                left = left / right

        return left

    def parse_power(self) -> float:
        """Parse ** (right-associative)"""
        base = self.parse_unary()

        if self.peek() and self.peek()[0] == 'OP' and self.peek()[1] == '**':
            self.consume()
            exponent = self.parse_power()  # Right-associative
            return base ** exponent

        return base

    def parse_unary(self) -> float:
        """Parse unary + and -"""
        if self.peek() and self.peek()[0] == 'OP' and self.peek()[1] in ('+', '-'):
            op = self.consume()[1]
            operand = self.parse_unary()
            if op == '+':
                return +operand
            else:
                return -operand

        return self.parse_primary()

    def parse_primary(self) -> float:
        """Parse numbers and parenthesized expressions"""
        token = self.peek()

        if token is None:
            raise ValueError("Unexpected end of expression")

        if token[0] == 'NUM':
            self.consume()
            return token[1]

        if token[0] == 'OP' and token[1] == '(':
            self.consume()
            result = self.parse_additive()
            if not self.peek() or self.peek()[1] != ')':
                raise ValueError("Expected closing parenthesis")
            self.consume()
            return result

        raise ValueError(f"Unexpected token: {token}")

def calc(expr: str) -> float:
    tokens = tokenize(expr)
    parser = Parser(tokens)
    return parser.parse()
