class JSONParser:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.length = len(text)

    def peek(self):
        if self.pos >= self.length:
            return None
        return self.text[self.pos]

    def consume(self):
        char = self.peek()
        self.pos += 1
        return char

    def skip_whitespace(self):
        while self.pos < self.length:
            c = self.text[self.pos]
            if c in ' \t\n\r':
                self.pos += 1
            else:
                break

    def parse(self):
        self.skip_whitespace()
        if self.pos >= self.length:
            raise ValueError("Empty input")
        value = self.parse_value()
        self.skip_whitespace()
        if self.pos < self.length:
            raise ValueError("Trailing characters")
        return value

    def parse_value(self):
        self.skip_whitespace()
        c = self.peek()
        if c == '{':
            return self.parse_object()
        elif c == '[':
            return self.parse_array()
        elif c == '"':
            return self.parse_string()
        elif c == 't' or c == 'f' or c == 'n':
            return self.parse_literal()
        elif c == '-' or (c is not None and c.isdigit()):
            return self.parse_number()
        else:
            raise ValueError(f"Unexpected character: {c}")

    def parse_object(self):
        self.consume()  # {
        obj = {}
        self.skip_whitespace()
        if self.peek() == '}':
            self.consume()
            return obj

        while True:
            self.skip_whitespace()
            key = self.parse_string()
            self.skip_whitespace()
            if self.peek() != ':':
                raise ValueError("Expected ':'")
            self.consume()  # :
            self.skip_whitespace()
            val = self.parse_value()
            obj[key] = val

            self.skip_whitespace()
            c = self.peek()
            if c == '}':
                self.consume()
                return obj
            elif c == ',':
                self.consume()
                self.skip_whitespace()
                if self.peek() == '}':
                    raise ValueError("Trailing comma in object")
            else:
                raise ValueError("Expected ',' or '}'")

    def parse_array(self):
        self.consume()  # [
        arr = []
        self.skip_whitespace()
        if self.peek() == ']':
            self.consume()
            return arr

        while True:
            self.skip_whitespace()
            val = self.parse_value()
            arr.append(val)

            self.skip_whitespace()
            c = self.peek()
            if c == ']':
                self.consume()
                return arr
            elif c == ',':
                self.consume()
                self.skip_whitespace()
                if self.peek() == ']':
                    raise ValueError("Trailing comma in array")
            else:
                raise ValueError("Expected ',' or ']'")

    def parse_string(self):
        if self.peek() != '"':
            raise ValueError("Expected '\"'")
        self.consume()
        res = []
        while True:
            c = self.peek()
            if c is None:
                raise ValueError("Unterminated string")
            if c == '"':
                self.consume()
                return "".join(res)
            if c == '\\':
                self.consume()
                esc = self.peek()
                if esc is None:
                    raise ValueError("Unterminated string escape")
                if esc == 'u':
                    self.consume()
                    hex_str = ""
                    for _ in range(4):
                        h = self.peek()
                        if h is None:
                            raise ValueError("Invalid unicode escape")
                        if not ('0' <= h <= '9' or 'a' <= h.lower() <= 'f'):
                            raise ValueError("Invalid unicode escape")
                        hex_str += h
                        self.consume()
                    try:
                        code_point = int(hex_str, 16)
                        res.append(chr(code_point))
                    except ValueError:
                        raise ValueError("Invalid unicode escape")
                elif esc == '"':
                    res.append('"')
                    self.consume()
                elif esc == '\\':
                    res.append('\\')
                    self.consume()
                elif esc == '/':
                    res.append('/')
                    self.consume()
                elif esc == 'b':
                    res.append('\b')
                    self.consume()
                elif esc == 'f':
                    res.append('\f')
                    self.consume()
                elif esc == 'n':
                    res.append('\n')
                    self.consume()
                elif esc == 'r':
                    res.append('\r')
                    self.consume()
                elif esc == 't':
                    res.append('\t')
                    self.consume()
                else:
                    raise ValueError(f"Invalid escape sequence: \\{esc}")
            elif ord(c) < 0x20:
                raise ValueError("Control character in string")
            else:
                res.append(c)
                self.consume()

    def parse_number(self):
        start_pos = self.pos
        neg = False
        if self.peek() == '-':
            neg = True
            self.consume()

        if self.peek() is None or not self.peek().isdigit():
            raise ValueError("Invalid number")

        if self.peek() == '0':
            self.consume()
            if self.peek() and self.peek().isdigit():
                raise ValueError("Leading zeros not allowed")
        else:
            while self.peek() and self.peek().isdigit():
                self.consume()

        is_float = False
        if self.peek() == '.':
            is_float = True
            self.consume()
            if self.peek() is None or not self.peek().isdigit():
                raise ValueError("Invalid number fraction")
            while self.peek() and self.peek().isdigit():
                self.consume()

        if self.peek() and self.peek().lower() == 'e':
            is_float = True
            self.consume()
            if self.peek() and self.peek() in '+-':
                self.consume()
            if self.peek() is None or not self.peek().isdigit():
                raise ValueError("Invalid number exponent")
            while self.peek() and self.peek().isdigit():
                self.consume()

        num_str = self.text[start_pos:self.pos]
        if is_float:
            return float(num_str)
        else:
            return int(num_str)

    def parse_literal(self):
        c = self.peek()
        if c == 't':
            if self.text[self.pos:self.pos+4] == 'true':
                self.pos += 4
                return True
        elif c == 'f':
            if self.text[self.pos:self.pos+5] == 'false':
                self.pos += 5
                return False
        elif c == 'n':
            if self.text[self.pos:self.pos+4] == 'null':
                self.pos += 4
                return None
        raise ValueError("Invalid literal")


def parse_json(text: str) -> object:
    parser = JSONParser(text)
    return parser.parse()
