import datetime

def business_days(start: str, end: str, holidays: list[str]) -> int:
    s = datetime.date.fromisoformat(start)
    e = datetime.date.fromisoformat(end)

    if e < s:
        return -business_days(end, start, holidays)

    if s == e:
        return 0

    delta_days = (e - s).days
    full_weeks = delta_days // 7
    weekdays_count = full_weeks * 5

    remainder = delta_days % 7
    current_weekday = s.weekday()

    for i in range(remainder):
        if (current_weekday + i) % 7 < 5:
            weekdays_count += 1

    holiday_set = set()
    for h_str in holidays:
        if start <= h_str < end:
            try:
                h = datetime.date.fromisoformat(h_str)
                if h.weekday() < 5:
                    holiday_set.add(h)
            except ValueError:
                continue

    return weekdays_count - len(holiday_set)
