import re

def eval_bool(expr: str, env: dict[str, bool]) -> bool:
    # Tokenize the expression
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i].isspace():
            i += 1
            continue
        if expr[i] in '()':
            tokens.append(expr[i])
            i += 1
        elif expr[i].isalpha() or expr[i] == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append(expr[i:j])
            i = j
        else:
            raise SyntaxError(f"Invalid character '{expr[i]}' at position {i}")

    # Parser state
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume(expected=None):
        nonlocal pos
        token = peek()
        if expected is not None and token != expected:
            raise SyntaxError(f"Expected '{expected}', got '{token}'")
        pos += 1
        return token

    def parse_or():
        left = parse_and()
        while peek() == 'or':
            consume('or')
            right = parse_and()
            left = left or right
        return left

    def parse_and():
        left = parse_not()
        while peek() == 'and':
            consume('and')
            right = parse_not()
            left = left and right
        return left

    def parse_not():
        if peek() == 'not':
            consume('not')
            return not parse_not()
        return parse_primary()

    def parse_primary():
        token = peek()
        if token == '(':
            consume('(')
            result = parse_or()
            consume(')')
            return result
        elif token == 'true':
            consume('true')
            return True
        elif token == 'false':
            consume('false')
            return False
        elif token and (token[0].isalpha() or token[0] == '_'):
            consume(token)
            if token not in env:
                raise KeyError(token)
            return env[token]
        else:
            raise SyntaxError(f"Unexpected token: {token}")

    result = parse_or()
    if pos < len(tokens):
        raise SyntaxError(f"Unexpected token: {tokens[pos]}")
    return result

