def words_to_number(text: str) -> int:
    ones = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9,
        'ten': 10, 'eleven': 11, 'twelve': 12, 'thirteen': 13,
        'fourteen': 14, 'fifteen': 15, 'sixteen': 16, 'seventeen': 17,
        'eighteen': 18, 'nineteen': 19
    }
    tens = {
        'twenty': 20, 'thirty': 30, 'forty': 40, 'fifty': 50,
        'sixty': 60, 'seventy': 70, 'eighty': 80, 'ninety': 90
    }
    scales = {
        'hundred': 100,
        'thousand': 1000,
        'million': 1000000,
        'billion': 1000000000
    }

    # Normalize hyphens to spaces for consistent tokenization
    text = text.replace('-', ' ')
    words = text.split()

    if not words:
        return 0

    negative = False
    if words[0] == 'minus':
        negative = True
        words = words[1:]

    if not words:
        return 0

    total = 0
    current = 0

    for word in words:
        if word == 'and':
            continue

        if word in ones:
            current += ones[word]
        elif word in tens:
            current += tens[word]
        elif word in scales:
            scale_val = scales[word]
            if scale_val == 100:
                current *= 100
            else:
                total += current * scale_val
                current = 0

    total += current

    return -total if negative else total
